on-submit:
  |  
    // Display the content of the JSON object
    var jsonObject = sender.data;

    // Create a table element with column headers "Target IP Address", "Open Ports", and "Timestamp"
    let columns = ["Target IP Address", "Open Ports", "Timestamp"];
    var rows = [];

    for (let i in jsonObject) {
      if (i === 0 || i === 1) {
        // Add a row with the header
        rows.push({
          column: columns[i - 1],
          value: `${jsonObject[targetIpAddress][targetPort]}`,
          style: "width: 20px; text-align: right;"
        });
      } else if (i === 3) {
        // Add a row with the header
        rows.push({
          column: columns[i - 1],
          value: `${jsonObject[targetIpAddress][targetPort]}`,
          style: "width: 20px; text-align: right;"
        });
      }
    }

    // Generate the HTML content of the dialog box
    var output = `
      <table>
        ${columns.map((column) => `
          <tr>
            <td>${column}</td>
            <td>Open Ports</td>
            <td>${rows[0].value}</td>
            <td>${rows[1].value}</td>
            <td>${rows[2].value}</td>
            <td>${rows[3].value}</td>
          </tr>
        `).join('')}
      </table>
    `;

    // Send the generated HTML to the copilot
    sender.sendResponse(output);
